        static void execute(VaultNode from, VaultNode to, CrystalAmount amount) throws InsufficientCrystalsException {
            if (from.getBalance() < amount.getValue()) {
                throw new InsufficientCrystalsException("Insufficient crystals");
            }
            from.withdraw(amount.getValue());
            to.deposit(amount.getValue());
        }
    }

    public static CrystalAmount newCrystalAmount(int value) {
        return new SimpleCrystalAmount(value);
    }

    public static void transferCrystals(VaultNode from, VaultNode to, CrystalAmount amount)
            throws InsufficientCrystalsException {
        int fromHash = System.identityHashCode(from);
        int toHash = System.identityHashCode(to);
        if (fromHash < toHash) {
            synchronized (from) {
                synchronized (to) {
                    TransferRite.execute(from, to, amount);
                }
            }
        } else if (fromHash > toHash) {
            synchronized (to) {
                synchronized (from) {
                    TransferRite.execute(from, to, amount);
                }
            }
        } else {
            synchronized (tieLock) {
                synchronized (from) {
                    synchronized (to) {
                        TransferRite.execute(from, to, amount);
                    }
                }
            }
        }
    }
}

