class MysticCAS {
    private int value;

    public synchronized int get() {
        return value;
    }

    public synchronized int compareAndSwap(int expected, int newValue) {
        int old = value;
        if (value == expected) {
            value = newValue;
        }
        return old;
    }
}

class DragonScaleCounter {
