        ExecutorService es = Executors.newFixedThreadPool(3);
        Future<?> f1 = es.submit(() -> set.add(1));
        Future<?> f2 = es.submit(() -> set.add(2));
        f1.get();
        f2.get();
        Future<?> f3 = es.submit(() -> {
